function PriorityBadge({ priority }: { priority: Priority }) {
    const meta = PRIORITY_META[priority];
    return (
        <span className={cn("text-[10px] font-bold tracking-wider uppercase px-2 py-0.5 rounded", meta.bg, meta.color)}>
            {priority}
        </span>
    );
