/**
 * CAIQ Enhance API Route — Step 3: AI Enhancement
 * 
 * Two-stage SSE streaming:
 *   Stage 1: Tier 2 AI Semantic Matching
 *   Stage 2: Tier 3 AI Context Synthesis
 * 
 * Accepts questions + source entries + org profile.
 * Streams progress events to the frontend.
 */

import { NextRequest } from 'next/server';
import {
    semanticMatch,
    contextGenerate,
    type OrgProfile,
} from '@/lib/caiq/caiq-answer-engine';
import type { AnsweredQuestion } from '@/lib/caiq/caiq-knowledge-base';
import type { SourceEntry } from '@/lib/caiq/caiq-answer-engine';
import { getAIProvider } from '@/lib/ai/engine';
import { parseBodyWithZod, caiqEnhanceBodySchema, log } from '@/lib/api-validation';

export async function POST(request: NextRequest) {
    try {
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, caiqEnhanceBodySchema);
        if ('error' in parsed) return parsed.error;

        const {
            questions,
            sourceEntries,
            profile,
        } = parsed.data as unknown as {
            questions: AnsweredQuestion[];
            sourceEntries: SourceEntry[];
            profile: OrgProfile;
        };

        const provider = getAIProvider();
        const aiGenerateContent = provider.generateContent.bind(provider);
        const encoder = new TextEncoder();

        const stream = new ReadableStream({
            async start(controller) {
                const send = (event: string, data: any) => {
                    controller.enqueue(encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));
                };

                try {
                    let currentQuestions = questions;
                    const unmatchedCount = questions.filter(q => q.source === 'manual').length;

                    // ── Stage 1: Tier 2 Semantic Matching ──
                    send('stage', { stage: 'semantic', message: 'Running AI semantic matching...', total: unmatchedCount });

                    if (sourceEntries && sourceEntries.length > 0) {
                        currentQuestions = await semanticMatch(
                            currentQuestions,
                            sourceEntries,
                            profile,
                            aiGenerateContent,
                            'authenticated-user',
                            'gemini-1.5-pro',
                            (processed, total) => {
                                send('progress', {
                                    stage: 'semantic',
                                    processed,
                                    total,
                                    message: `Semantic matching: ${processed}/${total} questions`,
                                });
                            },
                        );

                        const semanticMatched = currentQuestions.filter(q => q.source === 'semantic').length;
                        send('stage_complete', {
                            stage: 'semantic',
                            matched: semanticMatched,
                            message: `Semantic matching complete: ${semanticMatched} matches found`,
                        });
                    } else {
                        send('stage_complete', {
                            stage: 'semantic',
                            matched: 0,
                            message: 'No source entries — skipping semantic matching',
                        });
                    }

                    // ── Stage 2: Tier 3 Context Generation ──
                    const remainingUnmatched = currentQuestions.filter(q => q.source === 'manual').length;
                    send('stage', { stage: 'context', message: 'Running AI context generation...', total: remainingUnmatched });

                    if (remainingUnmatched > 0 && sourceEntries && sourceEntries.length > 0) {
                        currentQuestions = await contextGenerate(
                            currentQuestions,
                            sourceEntries,
                            profile,
                            aiGenerateContent,
                            'authenticated-user',
                            'gemini-1.5-pro',
                            (processed, total) => {
                                send('progress', {
                                    stage: 'context',
                                    processed,
                                    total,
                                    message: `Context synthesis: ${processed}/${total} questions`,
                                });
                            },
                        );

                        const contextGenerated = currentQuestions.filter(q => q.source === 'context').length;
                        send('stage_complete', {
                            stage: 'context',
                            matched: contextGenerated,
                            message: `Context synthesis complete: ${contextGenerated} answers generated`,
                        });
                    } else {
                        send('stage_complete', {
                            stage: 'context',
                            matched: 0,
                            message: remainingUnmatched === 0
                                ? 'All questions answered — no context generation needed'
                                : 'No source entries for context synthesis',
                        });
                    }

                    // ── Final result ──
                    send('complete', {
                        questions: currentQuestions,
                        stats: {
                            a2a: currentQuestions.filter(q => q.source === 'a2a').length,
                            semantic: currentQuestions.filter(q => q.source === 'semantic').length,
                            context: currentQuestions.filter(q => q.source === 'context').length,
                            manual: currentQuestions.filter(q => q.source === 'manual').length,
                        },
                    });

                } catch (error) {
                    console.error('[CAIQ Enhance] Stream error:', error);
                    send('error', {
                        message: error instanceof Error ? error.message : 'AI enhancement failed',
                    });
                } finally {
                    controller.close();
                }
            },
        });

        return new Response(stream, {
            headers: {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache',
                'Connection': 'keep-alive',
            },
        });

    } catch (error) {
        console.error('[CAIQ Enhance] Error:', error);
        return new Response(
            JSON.stringify({ error: error instanceof Error ? error.message : 'Enhancement failed' }),
            { status: 500, headers: { 'Content-Type': 'application/json' } },
        );
    }
}

/**
 * CAIQ Export API Route
 *
 * POST /api/caiq/export
 * Body: { questions: AnsweredQuestion[], fileName?: string }
 * Returns: .xlsx file download populated with questions and answers.
 */

import { NextRequest, NextResponse } from 'next/server';
import ExcelJS from 'exceljs';
import type { AnsweredQuestion } from '@/lib/caiq/caiq-knowledge-base';
import { parseBodyWithZod, caiqExportBodySchema, log } from '@/lib/api-validation';

const CONFIDENCE_LABEL: Record<string, string> = {
    a2a: 'Direct Match (KB)',
    kb: 'KB Match',
    semantic: 'Semantic Match',
    context: 'AI Generated',
    manual: 'Not Answered',
};

export async function POST(request: NextRequest) {
    try {
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, caiqExportBodySchema);
        if ('error' in parsed) return parsed.error;

        const { questions, fileName = 'questionnaire-answers' } = parsed.data as unknown as {
            questions: AnsweredQuestion[];
            fileName?: string;
        };

        if (!questions || questions.length === 0) {
            return NextResponse.json({ error: 'No questions provided' }, { status: 400 });
        }

        // Build the workbook
        const workbook = new ExcelJS.Workbook();
        workbook.creator = 'Aegis CISO — Knowledge Base';
        workbook.created = new Date();

        const ws = workbook.addWorksheet('Questionnaire Answers', {
            views: [{ state: 'frozen', ySplit: 1 }],
        });

        // Header row
        ws.columns = [
            { header: '#', key: 'num', width: 6 },
            { header: 'Question ID', key: 'id', width: 14 },
            { header: 'Question', key: 'question', width: 55 },
            { header: 'Answer', key: 'answer', width: 60 },
            { header: 'Yes / No', key: 'yesNo', width: 12 },
            { header: 'Confidence', key: 'confidence', width: 13 },
            { header: 'Source', key: 'source', width: 20 },
            { header: 'Domain', key: 'domain', width: 16 },
        ];

        // Style header
        const headerRow = ws.getRow(1);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 10 };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF18181B' } };
        headerRow.alignment = { vertical: 'middle', horizontal: 'left', wrapText: false };
        headerRow.height = 20;

        // Data rows
        questions.forEach((q, idx) => {
            const confLabel = q.confidence;
            const confPct = confLabel === 'high' ? 95 : confLabel === 'medium' ? 70 : 45;
            const row = ws.addRow({
                num: idx + 1,
                id: q.questionId || `Q${idx + 1}`,
                question: q.questionText,
                answer: q.answer || '',
                yesNo: q.yesNo || '',
                confidence: q.source === 'manual' ? 'N/A' : `${confLabel} (${confPct}%)`,
                source: CONFIDENCE_LABEL[q.source] || q.source,
                domain: (q as unknown as { domain?: string }).domain || '',
            });

            row.alignment = { wrapText: true, vertical: 'top' };
            row.height = 36;

            // Colour-code by confidence
            const confCell = row.getCell('confidence');
            if (q.source === 'manual') {
                confCell.font = { color: { argb: 'FFF87171' } };
            } else if (confLabel === 'high') {
                confCell.font = { color: { argb: 'FF34D399' } };
            } else if (confLabel === 'medium') {
                confCell.font = { color: { argb: 'FFFBBF24' } };
            } else {
                confCell.font = { color: { argb: 'FFFB923C' } };
            }
        });

        // Borders on all cells
        ws.eachRow((row) => {
            row.eachCell((cell) => {
                cell.border = {
                    bottom: { style: 'thin', color: { argb: 'FF27272A' } },
                };
            });
        });

        // Write to buffer
        const buffer = await workbook.xlsx.writeBuffer();

        return new NextResponse(buffer, {
            status: 200,
            headers: {
                'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                'Content-Disposition': `attachment; filename="${fileName.replace(/\.xlsx?$/, '')}.xlsx"`,
                'Content-Length': buffer.byteLength.toString(),
            },
        });

    } catch (error) {
        console.error('[CAIQ Export]', error);
        return NextResponse.json(
            { error: error instanceof Error ? error.message : 'Export failed' },
            { status: 500 }
        );
    }
}

