    const dbMap = new Map(dbRows.map((r) => [r.integrationId, r]));

    // Merge registry with DB status
    const integrations = INTEGRATIONS_REGISTRY.map((def) => {
        const row = dbMap.get(def.id);
        return {
            id: def.id,
            name: def.name,
            description: def.description,
            category: def.category,
            logo: def.logo,
            popular: def.popular ?? false,
            phase1: def.phase1,
            status: row?.status ?? 'available',
            connectedAt: row?.connectedAt ?? null,
            connectedBy: row?.connectedBy ?? null,
            lastTestedAt: row?.lastTestedAt ?? null,
            lastTestResult: row?.lastTestResult ?? null,
        };
    });

    return NextResponse.json({ integrations });
}

import { NextResponse } from 'next/server';
import { jiraConnector } from '@/lib/jira/jira-connector';
import { parseBodyWithZod, jiraIssueBodySchema, log } from '@/lib/api-validation';

// Initialize connector from env vars if available
function initConnector() {
    const baseUrl = process.env.JIRA_BASE_URL;
    const email = process.env.JIRA_EMAIL;
    const apiToken = process.env.JIRA_API_TOKEN;
    const projectKey = process.env.JIRA_PROJECT_KEY || 'SEC';

    if (baseUrl && email && apiToken) {
        jiraConnector.configure({ baseUrl, email, apiToken, projectKey });
    }
}

// GET /api/jira — Check connection status
export async function GET() {
    initConnector();

    if (!jiraConnector.isConfigured()) {
        return NextResponse.json({
            connected: false,
            message: 'Jira not configured. Set JIRA_BASE_URL, JIRA_EMAIL, and JIRA_API_TOKEN env vars.',
            mode: 'LOCAL',
        });
    }

    const result = await jiraConnector.testConnection();
    return NextResponse.json({
        connected: result.ok,
        message: result.message,
        mode: result.ok ? 'CONNECTED' : 'ERROR',
    });
}

// POST /api/jira — Create a Jira issue
export async function POST(request: Request) {
    initConnector();

    try {
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, jiraIssueBodySchema);
        if ('error' in parsed) return parsed.error;

        if (!jiraConnector.isConfigured()) {
            return NextResponse.json({
                success: false,
                error: 'Jira not configured. Ticket saved locally only.',
                mode: 'LOCAL',
            }, { status: 503 });
        }

        const result = await jiraConnector.createIssue(parsed.data as any);

        return NextResponse.json({
            success: true,
            key: result.key,
            id: result.id,
            self: result.self,
            mode: 'SYNCED',
        });
    } catch (error) {
        return NextResponse.json({
            success: false,
            error: (error as Error).message,
            mode: 'FAILED',
        }, { status: 500 });
    }
}

