import { parseBodyWithZod, knowledgePatchBodySchema, log } from '@/lib/api-validation';

const repo = new KnowledgeRepository(prisma as any);


// ─── PATCH — Update / Approve ───────────────

export async function PATCH(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const { id } = await params;
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, knowledgePatchBodySchema);
        if ('error' in parsed) return parsed.error;
        const body = parsed.data as any;

        // Special mode: approve
        if (body.action === 'approve') {
            const entry = await repo.approveEntry(id, body.approvedBy || 'admin');
            return NextResponse.json({ success: true, entry });
        }

        // Special mode: record usage
        if (body.action === 'recordUsage') {
            const entry = await repo.recordUsage(id);
            return NextResponse.json({ success: true, entry });
        }

        // General update
        const entry = await repo.updateEntry(id, body);
        return NextResponse.json({ success: true, entry });
    } catch (error: any) {
        log('error', 'knowledge/[id]/PATCH', 'Failed to update entry', error);
        return NextResponse.json(
            { error: error.message || 'Failed to update entry' },
            { status: 500 }
        );
    }
}


// ─── DELETE — Remove ────────────────────────

export async function DELETE(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const { id } = await params;
        await repo.deleteEntry(id);
        return NextResponse.json({ success: true });
    } catch (error: any) {
        console.error('[Knowledge API] DELETE error:', error);
        return NextResponse.json(
            { error: error.message || 'Failed to delete entry' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import ExcelJS from 'exceljs';

export async function GET(req: NextRequest) {
    try {
        const { searchParams } = new URL(req.url);
        const format = searchParams.get('format') || 'xlsx';
        const companyId = searchParams.get('companyId');
        const productId = searchParams.get('productId');

        // Fetch common knowledge entries
        const entries = await prisma.knowledgeEntry.findMany({
            orderBy: { domain: 'asc' }
        });

        // Fetch overrides if context is specified
        let companyOverrides: any[] = [];
        let productOverrides: any[] = [];

        if (companyId) {
            companyOverrides = await (prisma as any).knowledgeOverride.findMany({
                where: { scope: 'COMPANY', companyId },
            });
        }
        if (productId) {
            productOverrides = await (prisma as any).knowledgeOverride.findMany({
                where: { scope: 'PRODUCT', productId },
            });
        }

        // ─── JSON Format ─────────────────────────
        if (format === 'json') {
            const exportData = {
                version: '2.0',
                exportedAt: new Date().toISOString(),
                scope: {
                    companyId: companyId || null,
                    productId: productId || null,
                },
                stats: {
                    commonEntries: entries.length,
                    companyOverrides: companyOverrides.length,
                    productOverrides: productOverrides.length,
                },
                commonEntries: entries.map(e => ({
                    id: e.id,
                    domain: e.domain,
                    category: e.category,
                    questionText: e.questionText,
                    questionNormalized: e.questionNormalized,
                    answerType: e.answerType,
                    answerText: e.answerText,
                    evidence: e.evidence,
                    keywords: e.keywords,
                    confidence: e.confidence,
                    usageCount: e.usageCount,
                    source: e.source,
                    frameworks: e.frameworks,
                    jurisdiction: e.jurisdiction,
                    tags: e.tags,
                    approvedBy: e.approvedBy,
                })),
                companyOverrides: companyOverrides.map((o: any) => ({
                    id: o.id,
                    knowledgeEntryId: o.knowledgeEntryId,
                    scope: o.scope,
                    companyId: o.companyId,
                    questionText: o.questionText,
                    answerType: o.answerType,
                    answerText: o.answerText,
                    notes: o.notes,
                })),
                productOverrides: productOverrides.map((o: any) => ({
                    id: o.id,
                    knowledgeEntryId: o.knowledgeEntryId,
                    scope: o.scope,
                    productId: o.productId,
                    questionText: o.questionText,
                    answerType: o.answerType,
                    answerText: o.answerText,
                    notes: o.notes,
                })),
            };

            const json = JSON.stringify(exportData, null, 2);
            return new NextResponse(json, {
                status: 200,
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Disposition': 'attachment; filename="koso_knowledge_base.json"',
                },
            });
        }

        // ─── Excel Format (Default) ──────────────
        const workbook = new ExcelJS.Workbook();
        workbook.creator = 'Kōsō Intelligence';
        const sheet = workbook.addWorksheet('Knowledge Base');

        sheet.columns = [
            { header: 'ID', key: 'id', width: 36 },
            { header: 'Domain', key: 'domain', width: 15 },
            { header: 'Category', key: 'category', width: 25 },
            { header: 'Question', key: 'questionText', width: 60 },
            { header: 'Answer', key: 'answerText', width: 80 },
            { header: 'Answer Type', key: 'answerType', width: 15 },
            { header: 'Evidence', key: 'evidence', width: 30 },
            { header: 'Keywords', key: 'keywords', width: 40 },
            { header: 'Confidence', key: 'confidence', width: 15 },
            { header: 'Usage Count', key: 'usageCount', width: 15 },
            { header: 'Source', key: 'source', width: 25 },
        ];

        const headerRow = sheet.getRow(1);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF4F46E5' } };

        for (const entry of entries) {
            sheet.addRow({
                id: entry.id,
                domain: entry.domain,
                category: entry.category,
                questionText: entry.questionText,
                answerText: entry.answerText,
                answerType: entry.answerType || 'N/A',
                evidence: entry.evidence || '',
                keywords: entry.keywords || '',
                confidence: entry.confidence,
                usageCount: entry.usageCount,
                source: entry.source
            });
        }

        sheet.eachRow((row, rowNumber) => {
            if (rowNumber > 1) {
                row.getCell('questionText').alignment = { wrapText: true, vertical: 'top' };
                row.getCell('answerText').alignment = { wrapText: true, vertical: 'top' };
            }
        });

        const buffer = await workbook.xlsx.writeBuffer();

        return new NextResponse(buffer, {
            status: 200,
            headers: {
                'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                'Content-Disposition': 'attachment; filename="koso_knowledge_base.xlsx"',
            }
        });
    } catch (error) {
        console.error('[Knowledge Export API]', error);
        return NextResponse.json({ error: 'Failed to export knowledge base' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import ExcelJS from 'exceljs';
import { normalizeQuestion, extractKeywords } from '@/lib/knowledge/repository';

export async function POST(req: NextRequest) {
    try {
        const formData = await req.formData();
        const file = formData.get('file') as File;

        if (!file) {
            return NextResponse.json({ error: 'No file provided' }, { status: 400 });
        }

        const fileName = file.name.toLowerCase();

        // ─── JSON Import ─────────────────────────
        if (fileName.endsWith('.json')) {
            return handleJsonImport(file);
        }

        // ─── Excel Import (Default) ──────────────
        return handleExcelImport(file);

    } catch (error) {
        console.error('[Knowledge Import API]', error);
        return NextResponse.json({ error: 'Failed to process import file' }, { status: 500 });
    }
}

// ════════════════════════════════════════════
// JSON Import Handler
// ════════════════════════════════════════════

async function handleJsonImport(file: File) {
    const text = await file.text();
    let data: Record<string, unknown> & { commonEntries?: any[], companyOverrides?: any[], productOverrides?: any[], scope?: any };

    try {
        data = JSON.parse(text);
    } catch {
        return NextResponse.json({ error: 'Invalid JSON file' }, { status: 400 });
    }

    // Validate schema version
    if (!data.version || !data.commonEntries) {
        return NextResponse.json({ error: 'Invalid JSON format. Expected v2.0 schema with commonEntries array.' }, { status: 400 });
    }

    let importedCount = 0;
    let skippedCount = 0;
    let overrideCount = 0;

    // Import common entries
    for (const entry of data.commonEntries) {
        if (!entry.questionText || !entry.answerText) continue;

        const normalized = normalizeQuestion(entry.questionText);

        // Dedup check
        const existing = await prisma.knowledgeEntry.findFirst({
            where: { questionNormalized: normalized }
        });

        if (existing) {
            skippedCount++;
            continue;
        }

        await prisma.knowledgeEntry.create({
            data: {
                questionText: entry.questionText,
                questionNormalized: normalized,
                keywords: entry.keywords || extractKeywords(entry.questionText),
                domain: entry.domain || 'CUSTOM',
                category: entry.category || 'Imported',
                answerType: entry.answerType || 'CONDITIONAL',
                answerText: entry.answerText,
                evidence: entry.evidence || null,
                source: entry.source || 'JSON Import',
                frameworks: entry.frameworks || null,
                jurisdiction: entry.jurisdiction || null,
                tags: entry.tags || null,
                confidence: entry.confidence ?? 1.0,
                approvedBy: entry.approvedBy || 'SYSTEM',
                approvedAt: new Date(),
            }
        });
        importedCount++;
    }

    // Import company overrides
    if (data.companyOverrides && Array.isArray(data.companyOverrides)) {
        for (const override of data.companyOverrides) {
            if (!override.questionText || !override.answerText) continue;
            try {
                await prisma.knowledgeOverride.create({
                    data: {
                        knowledgeEntryId: override.knowledgeEntryId || null,
                        scope: 'COMPANY',
                        companyId: override.companyId || data.scope?.companyId || null,
                        questionText: override.questionText,
                        answerType: override.answerType || 'CONDITIONAL',
                        answerText: override.answerText,
                        notes: override.notes || null,
                    }
                });
                overrideCount++;
            } catch { /* skip on error - may have FK issues */ }
        }
    }

    // Import product overrides
    if (data.productOverrides && Array.isArray(data.productOverrides)) {
        for (const override of data.productOverrides) {
            if (!override.questionText || !override.answerText) continue;
            try {
                await prisma.knowledgeOverride.create({
                    data: {
                        knowledgeEntryId: override.knowledgeEntryId || null,
                        scope: 'PRODUCT',
                        productId: override.productId || data.scope?.productId || null,
                        questionText: override.questionText,
                        answerType: override.answerType || 'CONDITIONAL',
                        answerText: override.answerText,
                        notes: override.notes || null,
                    }
                });
                overrideCount++;
            } catch { /* skip on error */ }
        }
    }

    return NextResponse.json({
        success: true,
        message: `JSON Import complete. ${importedCount} entries imported, ${skippedCount} skipped, ${overrideCount} overrides created.`,
        importedCount,
        skippedCount,
        overrideCount,
    });
}

// ════════════════════════════════════════════
// Excel Import Handler
// ════════════════════════════════════════════

async function handleExcelImport(file: File) {
    const buffer = Buffer.from(await file.arrayBuffer());
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(buffer as unknown as ArrayBuffer);

    const sheet = workbook.getWorksheet(1);
    if (!sheet) {
        return NextResponse.json({ error: 'Excel file is empty or invalid' }, { status: 400 });
    }

    const headerRow = sheet.getRow(1);
    const headers: Record<string, number> = {};
    headerRow.eachCell((cell, colNumber) => {
        const val = cell.value?.toString().trim().toLowerCase();
        if (val) headers[val] = colNumber;
    });

    const qIdx = headers['question'] || headers['questiontext'];
    const aIdx = headers['answer'] || headers['answertext'];

    if (!qIdx || !aIdx) {
        return NextResponse.json({ error: 'Missing Required Columns: Question and Answer' }, { status: 400 });
    }

    const domIdx = headers['domain'];
    const catIdx = headers['category'];
    const srcIdx = headers['source'];

    let importedCount = 0;
    let skippedCount = 0;

    for (let rowNumber = 2; rowNumber <= sheet.rowCount; rowNumber++) {
        const row = sheet.getRow(rowNumber);
        const questionRaw = row.getCell(qIdx).value?.toString()?.trim();
        const answerRaw = row.getCell(aIdx).value?.toString()?.trim();

        if (!questionRaw || !answerRaw) continue;

        const domainRaw = domIdx ? row.getCell(domIdx).value?.toString()?.trim() : 'CUSTOM';
        const catRaw = catIdx ? row.getCell(catIdx).value?.toString()?.trim() : 'Imported';
        const sourceRaw = srcIdx ? row.getCell(srcIdx).value?.toString()?.trim() : `Imported: ${file.name}`;

        const normalized = normalizeQuestion(questionRaw);

        const existing = await prisma.knowledgeEntry.findFirst({
            where: { questionNormalized: normalized }
        });

        if (existing) {
            skippedCount++;
            continue;
        }

        await prisma.knowledgeEntry.create({
            data: {
                questionText: questionRaw,
                questionNormalized: normalized,
                keywords: extractKeywords(questionRaw),
                domain: domainRaw || 'CUSTOM',
                category: catRaw || 'Imported',
                answerType: answerRaw.toLowerCase().startsWith('yes') ? 'YES' : 'CONDITIONAL',
                answerText: answerRaw,
                source: sourceRaw || 'Manual Import',
                confidence: 1.0,
                approvedBy: 'SYSTEM',
                approvedAt: new Date(),
            }
        });
        importedCount++;
    }

    return NextResponse.json({
        success: true,
        message: `Import complete. Imported ${importedCount} entries. Skipped ${skippedCount} duplicates.`,
        importedCount,
        skippedCount
    });
}

/**
 * Knowledge Ingest API — Feed completed assessments into the repository
 *
 * POST /api/knowledge/ingest — Bulk ingest from completed CAIQ assessments
 */

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { KnowledgeRepository } from '@/lib/knowledge/repository';
import { parseBodyWithZod, knowledgeIngestBodySchema, log } from '@/lib/api-validation';

const repo = new KnowledgeRepository(prisma as any);


export async function POST(request: NextRequest) {
    try {
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, knowledgeIngestBodySchema);
        if ('error' in parsed) return parsed.error;
        const { questions, source, assessmentName } = parsed.data;

        const src = source || assessmentName || 'Assessment Import';

        // Transform AnsweredQuestion[] to IngestEntry[]
        const entries = questions
            .filter((q: any) => q.answer && q.answer.length > 5 && q.source !== 'manual')
            .map((q: any) => ({
                questionText: q.questionText,
                answerText: q.answer,
                answerType: q.yesNo || 'YES',
                evidence: q.evidenceRef || '',
                domain: q.domain || 'CUSTOM',
                category: q.category || 'General',
                confidence: q.confidence === 'high' ? 1.0
                    : q.confidence === 'medium' ? 0.7
                        : q.confidence === 'low' ? 0.4
                            : typeof q.confidence === 'number' ? q.confidence : 0.7,
            }));

        const result = await repo.bulkIngest(entries, src);

        return NextResponse.json({
            success: true,
            source: src,
            totalProcessed: questions.length,
            created: result.created,
            skipped: result.skipped,
        });
    } catch (error: any) {
        log('error', 'knowledge/ingest/POST', 'Failed to ingest knowledge entries', error);
        return NextResponse.json(
            { error: error.message || 'Failed to ingest knowledge entries' },
            { status: 500 }
        );
    }
}

/**
 * Knowledge Repository API — List & Create
 *
 * GET  /api/knowledge — Search/list entries with pagination & filters
 * POST /api/knowledge — Create single entry or bulk import
 */

import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { KnowledgeRepository } from '@/lib/knowledge/repository';
import { parseBodyWithZod, knowledgeCreateBodySchema, log } from '@/lib/api-validation';
import { logAudit } from '@/lib/audit/audit-service';

const repo = new KnowledgeRepository(prisma as any);


// ─── GET — Search & List ────────────────────

export async function GET(request: NextRequest) {
    try {
        const url = request.nextUrl;
        const filters = {
            query: url.searchParams.get('q') || undefined,
            domain: url.searchParams.get('domain') || undefined,
            category: url.searchParams.get('category') || undefined,
            answerType: url.searchParams.get('answerType') || undefined,
            source: url.searchParams.get('source') || undefined,
            approvedOnly: url.searchParams.get('approved') === 'true',
            jurisdiction: url.searchParams.get('jurisdiction') || undefined,
            tag: url.searchParams.get('tag') || undefined,
            page: parseInt(url.searchParams.get('page') || '1', 10),
            pageSize: Math.min(parseInt(url.searchParams.get('pageSize') || '50', 10), 200),
        };

        // Special mode: stats only
        if (url.searchParams.get('stats') === 'true') {
            const stats = await repo.getStats();
            return NextResponse.json(stats);
        }

        // Special mode: filter options
        if (url.searchParams.get('filters') === 'true') {
            const [domains, categories, sources] = await Promise.all([
                repo.getDistinctDomains(),
                repo.getDistinctCategories(),
                repo.getDistinctSources(),
            ]);
            return NextResponse.json({ domains, categories, sources });
        }

        const result = await repo.searchEntries(filters);
        return NextResponse.json(result);
    } catch (error: any) {
        console.error('[Knowledge API] GET error:', error);
        return NextResponse.json(
            { error: error.message || 'Failed to fetch knowledge entries' },
            { status: 500 }
        );
    }
}

// ─── POST — Create / Bulk Import ────────────

export async function POST(request: NextRequest) {
    try {
        const raw = await request.json().catch(() => ({}));
        const parsed = parseBodyWithZod(raw, knowledgeCreateBodySchema);
        if ('error' in parsed) return parsed.error;
        const body = parsed.data as any;

        // Bulk import mode
        if (Array.isArray(body.entries)) {
            const source = body.source || 'Manual Import';
            const result = await repo.bulkIngest(body.entries, source);
            await logAudit({
                action: 'IMPORT',
                category: 'COMPLIANCE',
                resource: 'KnowledgeEntry',
                description: `Bulk imported ${result.created} knowledge entries (${result.skipped} skipped)`,
                metadata: { source, created: result.created, skipped: result.skipped },
            });
            return NextResponse.json({
                success: true,
                created: result.created,
                skipped: result.skipped,
            });
        }

        // Single entry creation
        const entry = await repo.createEntry({
            questionText: body.questionText,
            answerText: body.answerText,
            answerType: body.answerType || 'YES',
            domain: body.domain || 'CUSTOM',
            category: body.category || 'General',
            evidence: body.evidence,
            source: body.source || 'Manual Entry',
            confidence: body.confidence,
            frameworks: body.frameworks,
            jurisdiction: body.jurisdiction,
            tags: body.tags,
        });

        await logAudit({
            action: 'CREATE',
            category: 'COMPLIANCE',
            resource: 'KnowledgeEntry',
            resourceId: entry.id,
            description: `Created knowledge entry: ${body.questionText?.slice(0, 60) ?? 'Unknown'}`,
        });

        return NextResponse.json({ success: true, entry }, { status: 201 });
    } catch (error: any) {
        log('error', 'knowledge/POST', 'Failed to create knowledge entry', error);
        return NextResponse.json(
            { error: error.message || 'Failed to create knowledge entry' },
            { status: 500 }
        );
    }
}

/**
 * CAIQ Questionnaire Automation API
 * 
 * POST /api/vendors/caiq — Upload Excel, process with KB + optional AI
 */

import { NextRequest, NextResponse } from 'next/server';
import {
    parseQuestionnaire,
    matchToKnowledgeBase,
    enhanceWithAI,
    computeResults,
    exportToExcel,
    type OrgProfile,
} from '@/lib/caiq/caiq-answer-engine';
import { getAIProvider, isAIConfigured } from '@/lib/ai/engine';

export async function POST(request: NextRequest) {
    try {
        const formData = await request.formData();
        const file = formData.get('file') as File | null;
        const mode = formData.get('mode') as string || 'template'; // 'template' | 'ai'
        const profileRaw = formData.get('profile') as string || '{}';

        if (!file) {
            return NextResponse.json(
                { error: 'No file uploaded. Please upload an Excel (.xlsx) file.' },
                { status: 400 }
            );
        }

        // Validate file type — be very lenient, xlsx library handles most formats
        const name = file.name.toLowerCase();
        const isAcceptable = name.endsWith('.xlsx') || name.endsWith('.xls')
            || name.endsWith('.csv') || name.endsWith('.xlsm')
            || file.type.includes('spreadsheet') || file.type.includes('excel')
            || file.type.includes('csv') || file.type === 'application/octet-stream'
            || file.type === '';

        if (!isAcceptable) {
            return NextResponse.json(
                { error: `Unsupported file type "${file.type}" (${file.name}). Please upload .xlsx, .xls, or .csv files.` },
                { status: 400 }
            );
        }

        // Parse org profile
        let profile: OrgProfile;
        try {
            profile = JSON.parse(profileRaw);
        } catch {
            profile = {
                industry: 'Technology',
                certifications: ['SOC 2 Type II', 'ISO 27001'],
                orgSize: 'Mid-size',
                cloudProvider: 'AWS',
                additionalContext: '',
            };
        }

        // Step 1: Parse the Excel file
        const buffer = await file.arrayBuffer();
        console.log(`[CAIQ API] File: ${file.name}, Size: ${buffer.byteLength} bytes, Type: ${file.type}`);

        const questions = await parseQuestionnaire(buffer);
        console.log(`[CAIQ API] Detected ${questions.length} questions`);

        if (questions.length === 0) {
            // Log more detail to help debug
            const ExcelJS = await import('exceljs');
            const wb = new ExcelJS.default.Workbook();
            await wb.xlsx.load(new Uint8Array(buffer) as any);
            const sheetInfo = wb.worksheets.map(ws => {
                let rowCount = 0;
                let maxCols = 0;
                ws.eachRow({ includeEmpty: false }, (row) => {
                    rowCount++;
                    const vals = row.values as any[];
                    if (vals.length > maxCols) maxCols = vals.length;
                });
                return `"${ws.name}" (${rowCount} rows, ~${maxCols} cols)`;
            }).join(', ');
            console.error(`[CAIQ API] No questions found. Sheets: [${sheetInfo}]`);

            return NextResponse.json(
                { error: `No questions detected. File has sheets: [${sheetInfo}]. Ensure the spreadsheet contains a column with questionnaire questions (text cells with 5+ characters).` },
                { status: 400 }
            );
        }

        // Step 2: Match to knowledge base (now queries DB-backed repo)
        let answered = await matchToKnowledgeBase(questions);

        // Step 3: Optionally enhance with AI
        if (mode === 'ai' && isAIConfigured()) {
            try {
                const provider = getAIProvider();
                const authCookie = request.cookies.get('astra-auth');
                const userId = authCookie?.value || 'authenticated-user';
                const modelName = (provider as any).modelName || 'gemini-1.5-pro';

                answered = await enhanceWithAI(
                    answered,
                    profile,
                    (prompt) => provider.generateContent(prompt),
                    userId,
                    modelName
                );
            } catch (error) {
                console.error('[CAIQ API] AI enhancement failed, returning KB-only results:', error);
                // Continue with KB results only
            }
        }

        // Step 4: Compute results
        const result = computeResults(answered);

        // Step 5: Feedback loop — ingest answered questions into Knowledge Repository
        try {
            const answeredForIngest = result.questions
                .filter((q: any) => q.answer && q.answer.length > 10 && q.source !== 'manual');
            if (answeredForIngest.length > 0) {
                await fetch(new URL('/api/knowledge/ingest', request.url), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        questions: answeredForIngest,
                        source: `Assessment: ${file.name}`,
                    }),
                });
                console.log(`[CAIQ API] Fed ${answeredForIngest.length} answers back to Knowledge Repository`);
            }
        } catch (feedbackErr) {
            console.warn('[CAIQ API] Knowledge feedback loop failed (non-blocking):', feedbackErr);
        }

        // Step 6: Generate export Excel
        const exportBuffer = await exportToExcel(result);
        const exportBase64 = exportBuffer.toString('base64');

        return NextResponse.json({
            success: true,
            fileName: file.name,
            mode,
            aiAvailable: isAIConfigured(),
            result: {
                totalQuestions: result.totalQuestions,
                answeredByA2A: result.answeredByA2A,
                answeredBySemantic: result.answeredBySemantic,
                answeredByContext: result.answeredByContext,
                unanswered: result.unanswered,
                coveragePct: result.coveragePct,
                domainBreakdown: result.domainBreakdown,
                questions: result.questions,
            },
            exportBase64,
        });
    } catch (error: any) {
        console.error('[CAIQ API] Processing error:', error);
        return NextResponse.json(
            { error: error.message || 'Failed to process questionnaire' },
            { status: 500 }
        );
    }
}

'use client';

import { useState, useRef, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import {
    Upload, FileSpreadsheet, ArrowRight, ArrowLeft, Download, Loader2,
    Check, XCircle, Edit3, BarChart3, Sparkles, Shield, Brain,
    RefreshCw, CheckCircle, AlertTriangle, Filter, Database, PlusCircle,
} from 'lucide-react';

// ────────────────────────────────────────────
// Types
// ────────────────────────────────────────────

type Step = 1 | 2 | 3 | 4;

interface CAIQResult {
    totalQuestions: number;
    answeredByA2A: number;
    answeredBySemantic: number;
    answeredByContext: number;
    unanswered: number;
    coveragePct: number;
    questions: AnsweredQuestion[];
    domainBreakdown: Record<string, { total: number; answered: number; pct: number }>;
}

interface AnsweredQuestion {
    rowIndex: number;
    questionId?: string;
    questionText: string;
    answer: string;
    yesNo: 'Yes' | 'No' | 'N/A' | '';
    confidence: 'high' | 'medium' | 'low';
    source: 'a2a' | 'semantic' | 'context' | 'manual';
    evidenceRef: string;
    addedToRepo?: boolean;
}

interface SourceEntry {
    rowIndex: number;
    questionId?: string;
    questionText: string;
    answerText: string;
    yesNo: 'Yes' | 'No' | 'N/A' | '';
}

// ────────────────────────────────────────────
// Constants
// ────────────────────────────────────────────

const CERTIFICATIONS = [
    { id: 'soc2', label: 'SOC 2 Type II' },
    { id: 'iso27001', label: 'ISO 27001' },
    { id: 'nis2', label: 'NIS 2' },
    { id: 'euai', label: 'EU AI Act' },
    { id: 'gdpr', label: 'GDPR' },
    { id: 'hipaa', label: 'HIPAA' },
    { id: 'pci', label: 'PCI DSS' },
];

const SOURCE_BADGES: Record<string, { bg: string; text: string; label: string; icon: string }> = {
    a2a: { bg: 'bg-emerald-500/15', text: 'text-emerald-400', label: 'A2A', icon: '🎯' },
    semantic: { bg: 'bg-blue-500/15', text: 'text-blue-400', label: 'SEM', icon: '🔗' },
    context: { bg: 'bg-violet-500/15', text: 'text-violet-400', label: 'CTX', icon: '🧠' },
    manual: { bg: 'bg-zinc-700/30', text: 'text-zinc-500', label: 'Manual', icon: '✍️' },
};

const CONFIDENCE_BADGES: Record<string, { bg: string; text: string; label: string }> = {
    high: { bg: 'bg-emerald-500/15', text: 'text-emerald-400', label: 'High' },
    medium: { bg: 'bg-amber-500/15', text: 'text-amber-400', label: 'Medium' },
    low: { bg: 'bg-red-500/15', text: 'text-red-400', label: 'Low' },
};

const STEPS = [
    { num: 1, label: 'Upload & Configure' },
    { num: 2, label: 'Parse & Match' },
    { num: 3, label: 'AI Enhancement' },
    { num: 4, label: 'Review & Export' },
];

// ════════════════════════════════════════════
// CAIQWizard Component
// ════════════════════════════════════════════

export default function CAIQWizard() {
    // Wizard step
    const [step, setStep] = useState<Step>(1);

    // Step 1: Upload & Configure
    const [sourceFile, setSourceFile] = useState<File | null>(null);
    const [targetFile, setTargetFile] = useState<File | null>(null);
    const [isDraggingSource, setIsDraggingSource] = useState(false);
    const [isDraggingTarget, setIsDraggingTarget] = useState(false);
    const sourceInputRef = useRef<HTMLInputElement>(null);
    const targetInputRef = useRef<HTMLInputElement>(null);

    const [selectedCerts, setSelectedCerts] = useState<string[]>(['soc2', 'iso27001']);
    const [orgProfile, setOrgProfile] = useState({
        industry: 'Technology',
        orgSize: 'Mid-size',
        cloudProvider: 'AWS',
        additionalContext: '',
    });

    // Step 2: Parse results
    const [result, setResult] = useState<CAIQResult | null>(null);
    const [sourceEntries, setSourceEntries] = useState<SourceEntry[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Step 3: AI Enhancement
    const [enhancing, setEnhancing] = useState(false);
    const [enhanceStage, setEnhanceStage] = useState<'semantic' | 'context' | 'done'>('semantic');
    const [enhanceProgress, setEnhanceProgress] = useState({ processed: 0, total: 0, message: '' });

    // Step 4: Review
    const [filterSource, setFilterSource] = useState<string>('all');
    const [filterConf, setFilterConf] = useState<string>('all');
    const [editingRow, setEditingRow] = useState<number | null>(null);
    const [editAnswer, setEditAnswer] = useState('');
    const [exporting, setExporting] = useState(false);
    const [addingToRepo, setAddingToRepo] = useState<number | null>(null);
    const [addingAll, setAddingAll] = useState(false);

    // ── File Handlers ──

    const handleSourceDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDraggingSource(false);
        const file = e.dataTransfer.files[0];
        if (file && /\.(xlsx|xls|csv)$/i.test(file.name)) {
            setSourceFile(file);
            setError(null);
        }
    }, []);

    const handleTargetDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDraggingTarget(false);
        const file = e.dataTransfer.files[0];
        if (file && /\.(xlsx|xls|csv)$/i.test(file.name)) {
            setTargetFile(file);
            setError(null);
        }
    }, []);

    const toggleCert = (certId: string) => {
        setSelectedCerts(prev =>
            prev.includes(certId)
                ? prev.filter(c => c !== certId)
                : [...prev, certId]
        );
    };

    // ── Step 2: Parse & Match ──

    const handleParse = async () => {
        if (!targetFile) return;
        setLoading(true);
        setError(null);

        try {
            const formData = new FormData();
            formData.append('target', targetFile);
            if (sourceFile) {
                formData.append('source', sourceFile);
            }

            const res = await fetch('/api/caiq/parse', { method: 'POST', body: formData });
            const data = await res.json();

            if (!res.ok) throw new Error(data.error || 'Parse failed');

            setResult(data.result);
            if (data.sourceStats) {
                // Store source entries — will be needed for AI stages
                // Reparse the source file client-side to get entries
                // Actually they come from the server in the response's result
            }
            setStep(2);
        } catch (err: any) {
            setError(err.message || 'Failed to parse files');
        } finally {
            setLoading(false);
        }
    };

    // ── Step 3: AI Enhancement (SSE) ──

    const handleEnhance = async () => {
        if (!result) return;
        setEnhancing(true);
        setEnhanceStage('semantic');
        setEnhanceProgress({ processed: 0, total: 0, message: 'Starting AI enhancement...' });
        setStep(3);
        setError(null);

        try {
            // Build the certifications list from selected checkboxes
            const certLabels = selectedCerts.map(id => CERTIFICATIONS.find(c => c.id === id)?.label || id);
            const profile = {
                ...orgProfile,
                certifications: certLabels,
            };

            // We need to send source entries for AI stages
            // Parse source file again to get entries (or we could have stored them from step 2)
            let srcEntries: SourceEntry[] = [];
            if (sourceFile) {
                const sourceFormData = new FormData();
                sourceFormData.append('target', sourceFile); // Reuse the parse endpoint
                // Actually let's just send what we have
                // The enhance route needs the source entries
                // For now, send the source file data via the parse endpoint first
                const srcRes = await fetch('/api/caiq/parse', {
                    method: 'POST',
                    body: (() => {
                        const fd = new FormData();
                        fd.append('target', sourceFile);
                        return fd;
                    })(),
                });
                if (srcRes.ok) {
                    const srcData = await srcRes.json();
                    // Convert the parsed questions to source entries
                    srcEntries = srcData.result.questions.map((q: any) => ({
                        rowIndex: q.rowIndex,
                        questionId: q.questionId,
                        questionText: q.questionText,
                        answerText: q.answer || q.originalAnswer || '',
                        yesNo: q.yesNo || '',
                    }));
                }
            }

            setSourceEntries(srcEntries);

            const res = await fetch('/api/caiq/enhance', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    questions: result.questions,
                    sourceEntries: srcEntries,
                    profile,
                }),
            });

            if (!res.ok) {
                const errData = await res.json();
                throw new Error(errData.error || 'Enhancement failed');
            }

            // Process SSE stream
            const reader = res.body!.getReader();
            const decoder = new TextDecoder();
            let buffer = '';

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                buffer += decoder.decode(value, { stream: true });
                const lines = buffer.split('\n');
                buffer = lines.pop() || '';

                let eventType = '';
                for (const line of lines) {
                    if (line.startsWith('event: ')) {
                        eventType = line.slice(7).trim();
                    } else if (line.startsWith('data: ') && eventType) {
                        try {
                            const data = JSON.parse(line.slice(6));

                            if (eventType === 'stage') {
                                setEnhanceStage(data.stage);
                                setEnhanceProgress({ processed: 0, total: data.total, message: data.message });
                            } else if (eventType === 'progress') {
                                setEnhanceProgress({
                                    processed: data.processed,
                                    total: data.total,
                                    message: data.message,
                                });
                            } else if (eventType === 'stage_complete') {
                                setEnhanceProgress(prev => ({ ...prev, message: data.message }));
                            } else if (eventType === 'complete') {
                                // Update result with enhanced questions
                                setResult(prev => prev ? {
                                    ...prev,
                                    questions: data.questions,
                                    answeredByA2A: data.stats.a2a,
                                    answeredBySemantic: data.stats.semantic,
                                    answeredByContext: data.stats.context,
                                    unanswered: data.stats.manual,
                                    coveragePct: Math.round(
                                        ((data.stats.a2a + data.stats.semantic + data.stats.context) / prev.totalQuestions) * 100
                                    ),
                                } : null);
                                setEnhanceStage('done');
                                setStep(4);
                            } else if (eventType === 'error') {
                                throw new Error(data.message);
                            }
                        } catch (parseErr) {
                            // Ignore parse errors in SSE
                        }
                        eventType = '';
                    }
                }
            }
        } catch (err: any) {
            setError(err.message || 'AI enhancement failed');
            setStep(2); // Go back
        } finally {
            setEnhancing(false);
        }
    };

    // ── Step 4: Review Actions ──

    const handleSaveEdit = (rowIndex: number) => {
        if (!result) return;
        const updated = result.questions.map(q =>
            q.rowIndex === rowIndex
                ? { ...q, answer: editAnswer, source: 'manual' as const, confidence: 'high' as const }
                : q
        );
        setResult({ ...result, questions: updated });
        setEditingRow(null);
        setEditAnswer('');
    };

    const handleExport = async () => {
        if (!result) return;
        setExporting(true);
        try {
            const res = await fetch('/api/caiq/export', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ result }),
            });

            if (!res.ok) throw new Error('Export failed');

            const blob = await res.blob();
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `CAIQ_Completed_${new Date().toISOString().slice(0, 10)}.xlsx`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setExporting(false);
        }
    };

    const handleReset = () => {
        setStep(1);
        setSourceFile(null);
        setTargetFile(null);
        setResult(null);
        setSourceEntries([]);
        setError(null);
        setEnhancing(false);
        setEnhanceStage('semantic');
    };

    const handleAddToRepo = async (q: AnsweredQuestion) => {
        if (!q.answer || q.answer.length < 5) return;
        setAddingToRepo(q.rowIndex);
        try {
            const res = await fetch('/api/knowledge/ingest', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    questions: [q],
                    source: `CAIQ Wizard (Row ${q.rowIndex})`,
                }),
            });
            if (!res.ok) throw new Error('Failed to add to repository');

            setResult(prev => prev ? {
                ...prev,
                questions: prev.questions.map(reqQ =>
                    reqQ.rowIndex === q.rowIndex ? { ...reqQ, addedToRepo: true } : reqQ
                )
            } : null);
        } catch (err: any) {
            setError(err.message || 'Failed to add to repository');
        } finally {
            setAddingToRepo(null);
        }
    };

    const handleAddAllManual = async () => {
        if (!result) return;
        const toAdd = result.questions.filter(q => q.source === 'manual' && q.answer && q.answer.length >= 5 && !q.addedToRepo);
        if (toAdd.length === 0) return;

        setAddingAll(true);
        try {
            const res = await fetch('/api/knowledge/ingest', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    questions: toAdd,
                    source: `CAIQ Wizard (${targetFile?.name || 'Bulk'})`,
                }),
            });
            if (!res.ok) throw new Error('Failed to bulk add to repository');

            setResult(prev => prev ? {
                ...prev,
                questions: prev.questions.map(reqQ =>
                    (reqQ.source === 'manual' && reqQ.answer && reqQ.answer.length >= 5) ? { ...reqQ, addedToRepo: true } : reqQ
                )
            } : null);
        } catch (err: any) {
            setError(err.message || 'Failed to bulk add to repository');
        } finally {
            setAddingAll(false);
        }
    };

    // Filter for review step
    const filteredQuestions = result?.questions.filter(q => {
        if (filterSource !== 'all' && q.source !== filterSource) return false;
        if (filterConf !== 'all' && q.confidence !== filterConf) return false;
        return true;
    }) || [];

    // ════════════════════════════════════════════
    // RENDER
    // ════════════════════════════════════════════

    return (
        <div className="space-y-6">
            {/* Progress Bar */}
            <div className="flex items-center justify-between px-2">
                {STEPS.map((s, i) => (
                    <div key={s.num} className="flex items-center flex-1">
                        <div className={`flex items-center gap-2 ${step >= s.num ? 'text-violet-400' : 'text-zinc-600'}`}>
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-all ${step > s.num ? 'bg-violet-500 border-violet-500 text-white' :
                                step === s.num ? 'border-violet-500 text-violet-400' :
                                    'border-zinc-700 text-zinc-600'
                                }`}>
                                {step > s.num ? <Check className="h-4 w-4" /> : s.num}
                            </div>
                            <span className="text-xs font-medium hidden sm:inline">{s.label}</span>
                        </div>
                        {i < STEPS.length - 1 && (
                            <div className={`flex-1 h-0.5 mx-3 rounded transition-all ${step > s.num ? 'bg-violet-500' : 'bg-zinc-800'
                                }`} />
                        )}
                    </div>
                ))}
            </div>

            {/* ════════════════════════════════════ */}
            {/* STEP 1: Upload & Configure          */}
            {/* ════════════════════════════════════ */}
            {step === 1 && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {/* Left: File Upload */}
                    <Card className="border-zinc-800/50 bg-zinc-900/40">
                        <CardHeader>
                            <CardTitle className="text-base flex items-center gap-2">
                                <FileSpreadsheet className="h-5 w-5 text-violet-400" />
                                Upload Files
                            </CardTitle>
                            <p className="text-xs text-zinc-500">Upload your source answers and the target questionnaire</p>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            {/* SOURCE File */}
                            <div>
                                <Label className="text-xs font-semibold text-emerald-400 uppercase tracking-wider mb-2 block">
                                    📥 Source File (Your Answered Q&A)
                                </Label>
                                <div
                                    onDragOver={e => { e.preventDefault(); setIsDraggingSource(true); }}
                                    onDragLeave={() => setIsDraggingSource(false)}
                                    onDrop={handleSourceDrop}
                                    onClick={() => sourceInputRef.current?.click()}
                                    className={`relative border-2 border-dashed rounded-lg p-4 text-center cursor-pointer transition-all ${isDraggingSource ? 'border-emerald-400 bg-emerald-500/5' :
                                        sourceFile ? 'border-emerald-500/30 bg-emerald-500/5' :
                                            'border-zinc-700 hover:border-zinc-600'
                                        }`}
                                >
                                    <input
                                        ref={sourceInputRef}
                                        type="file"
                                        accept=".xlsx,.xls,.csv"
                                        className="hidden"
                                        onChange={e => {
                                            const f = e.target.files?.[0];
                                            if (f) { setSourceFile(f); setError(null); }
                                        }}
                                    />
                                    {sourceFile ? (
                                        <div className="flex items-center gap-2 justify-center">
                                            <CheckCircle className="h-4 w-4 text-emerald-400" />
                                            <span className="text-sm text-emerald-300">{sourceFile.name}</span>
                                            <span className="text-xs text-zinc-500">({(sourceFile.size / 1024).toFixed(0)} KB)</span>
                                        </div>
                                    ) : (
                                        <>
                                            <Upload className="h-5 w-5 mx-auto text-zinc-500 mb-1" />
                                            <p className="text-xs text-zinc-500">
                                                <span className="text-emerald-400 hover:underline">Click</span> or drag your answered questionnaire
                                            </p>
                                        </>
                                    )}
                                </div>
                            </div>

                            {/* TARGET File */}
                            <div>
                                <Label className="text-xs font-semibold text-violet-400 uppercase tracking-wider mb-2 block">
                                    📤 Target File (Empty Questionnaire)
                                </Label>
                                <div
                                    onDragOver={e => { e.preventDefault(); setIsDraggingTarget(true); }}
                                    onDragLeave={() => setIsDraggingTarget(false)}
                                    onDrop={handleTargetDrop}
                                    onClick={() => targetInputRef.current?.click()}
                                    className={`relative border-2 border-dashed rounded-lg p-4 text-center cursor-pointer transition-all ${isDraggingTarget ? 'border-violet-400 bg-violet-500/5' :
                                        targetFile ? 'border-violet-500/30 bg-violet-500/5' :
                                            'border-zinc-700 hover:border-zinc-600'
                                        }`}
                                >
                                    <input
                                        ref={targetInputRef}
                                        type="file"
                                        accept=".xlsx,.xls,.csv"
                                        className="hidden"
                                        onChange={e => {
                                            const f = e.target.files?.[0];
