                        <div className="flex items-center gap-2">
                            <span className={`text-lg font-bold ${result.coveragePct >= 80 ? 'text-emerald-400' : result.coveragePct >= 50 ? 'text-amber-400' : 'text-red-400'}`}>
                                {result.coveragePct}%
                            </span>
