                                    <SelectItem value="semantic">🔗 Semantic</SelectItem>
                                    <SelectItem value="context">🧠 Context</SelectItem>
                                    <SelectItem value="manual">✍️ Manual</SelectItem>
                                </SelectContent>
                            </Select>
