                                )}
                                onClick={() => document.getElementById("evidence-file-input")?.click()}
                                onDragOver={(e) => e.preventDefault()}
                                onDrop={(e) => {
                                    e.preventDefault();
                                    const f = e.dataTransfer.files[0];
                                    if (f) { setUploadFile(f); setUploadMeta((m) => ({ ...m, title: f.name.replace(/\.[^/.]+$/, "") })); }
                                }}
                            >
                                <input
                                    id="evidence-file-input"
                                    type="file"
                                    className="hidden"
                                    accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg,.csv,.txt,.zip"
                                    onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        if (f) { setUploadFile(f); setUploadMeta((m) => ({ ...m, title: f.name.replace(/\.[^/.]+$/, "") })); }
                                    }}
                                />
                                {uploadFile ? (
                                    <div className="flex items-center justify-center gap-2">
                                        <FileText className="h-5 w-5 text-emerald-400" />
                                        <span className="text-sm">{uploadFile.name} ({formatSize(uploadFile.size)})</span>
                                    </div>
                                ) : (
                                    <div>
                                        <Upload className="h-8 w-8 mx-auto text-muted-foreground mb-2" />
                                        <p className="text-sm text-muted-foreground">Drag & drop or click to select</p>
                                        <p className="text-[10px] text-muted-foreground mt-1">PDF, DOCX, XLSX, PNG, JPG, CSV, TXT, ZIP — max 50MB</p>
                                    </div>
                                )}
                            </div>

                            {/* Metadata form */}
                            <div className="space-y-3">
                                <Input
                                    placeholder="Title"
                                    value={uploadMeta.title}
                                    onChange={(e) => setUploadMeta((m) => ({ ...m, title: e.target.value }))}
                                />
                                <Input
                                    placeholder="Description (optional)"
                                    value={uploadMeta.description}
                                    onChange={(e) => setUploadMeta((m) => ({ ...m, description: e.target.value }))}
                                />
                                <select
                                    className="w-full h-9 px-3 text-sm rounded-md border border-border bg-background text-foreground"
                                    value={uploadMeta.category}
                                    onChange={(e) => setUploadMeta((m) => ({ ...m, category: e.target.value }))}
                                >
                                    {CATEGORIES.map((c) => <option key={c} value={c}>{c.replace(/_/g, " ")}</option>)}
                                </select>
                                <Input
                                    placeholder="Tags (comma-separated: encryption, SOC2, ...)"
                                    value={uploadMeta.tags}
                                    onChange={(e) => setUploadMeta((m) => ({ ...m, tags: e.target.value }))}
                                />
                                <Input
                                    placeholder="Frameworks (comma-separated: ISO 27001:A.8.24, SOC 2:CC6.1, ...)"
                                    value={uploadMeta.frameworks}
                                    onChange={(e) => setUploadMeta((m) => ({ ...m, frameworks: e.target.value }))}
                                />
                                <div>
                                    <label className="text-xs text-muted-foreground block mb-1">Expiry Date (optional)</label>
                                    <Input
                                        type="date"
                                        value={uploadMeta.expiresAt}
                                        onChange={(e) => setUploadMeta((m) => ({ ...m, expiresAt: e.target.value }))}
                                    />
                                </div>
                            </div>

                            <Button className="w-full" disabled={!uploadFile || uploading} onClick={handleUpload}>
                                {uploading ? "Uploading..." : "Upload Evidence"}
                            </Button>
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* Detail Panel */}
            {selectedEvidence && (
                <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setSelectedEvidence(null)}>
                    <Card className="w-full max-w-2xl border-border max-h-[80vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
                        <CardContent className="p-6 space-y-4">
                            <div className="flex items-start justify-between">
                                <div>
                                    <h3 className="text-lg font-bold">{selectedEvidence.title}</h3>
                                    <p className="text-sm text-muted-foreground">{selectedEvidence.fileName}</p>
                                </div>
                                <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setSelectedEvidence(null)}>
                                    <X className="h-4 w-4" />
                                </Button>
                            </div>

                            {/* Detail fields */}
                            <div className="grid grid-cols-2 gap-3 text-xs">
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">Category</span>
                                    <Badge variant="outline" className={cn("text-[10px]", CATEGORY_COLORS[selectedEvidence.category])}>
                                        {selectedEvidence.category.replace(/_/g, " ")}
                                    </Badge>
                                </div>
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">Status</span>
                                    <Badge variant="outline" className={cn("text-[10px] gap-1", STATUS_STYLES[selectedEvidence.status]?.color)}>
                                        {STATUS_STYLES[selectedEvidence.status]?.icon}{STATUS_STYLES[selectedEvidence.status]?.label}
                                    </Badge>
                                </div>
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">File Size</span>
                                    <span className="font-mono">{formatSize(selectedEvidence.fileSize)}</span>
                                </div>
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">Uploaded By</span>
                                    <span>{selectedEvidence.uploadedByName || selectedEvidence.uploadedBy}</span>
                                </div>
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">Created</span>
                                    <span>{new Date(selectedEvidence.createdAt).toLocaleDateString()}</span>
                                </div>
                                <div>
                                    <span className="text-muted-foreground block mb-0.5">Expires</span>
                                    <span>{selectedEvidence.expiresAt ? new Date(selectedEvidence.expiresAt).toLocaleDateString() : "—"}</span>
                                </div>
                            </div>

                            {selectedEvidence.description && (
                                <div>
                                    <span className="text-xs text-muted-foreground block mb-1">Description</span>
                                    <p className="text-sm">{selectedEvidence.description}</p>
                                </div>
                            )}

                            {/* Frameworks */}
                            {selectedEvidence.frameworks?.length > 0 && (
                                <div>
                                    <span className="text-xs text-muted-foreground block mb-1">Frameworks</span>
                                    <div className="flex flex-wrap gap-1.5">
                                        {selectedEvidence.frameworks.map((f, i) => (
                                            <Badge key={i} variant="outline" className="text-[10px] bg-primary/5 border-primary/20">{f}</Badge>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Tags */}
                            {selectedEvidence.tags?.length > 0 && (
                                <div>
                                    <span className="text-xs text-muted-foreground block mb-1">Tags</span>
                                    <div className="flex flex-wrap gap-1.5">
                                        {selectedEvidence.tags.map((t, i) => (
                                            <Badge key={i} variant="secondary" className="text-[10px]">{t}</Badge>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Linked resources */}
                            <div>
                                <div className="flex items-center justify-between mb-2">
                                    <span className="text-xs text-muted-foreground">Linked Resources ({selectedEvidence.links.length})</span>
                                    <Button variant="outline" size="sm" className="h-7 text-xs gap-1" onClick={() => setShowLinkModal(true)}>
                                        <Plus className="h-3 w-3" />Add Link
                                    </Button>
                                </div>
                                {selectedEvidence.links.length > 0 ? (
                                    <div className="space-y-1.5">
                                        {selectedEvidence.links.map((link) => (
                                            <div key={link.id} className="flex items-center justify-between p-2 rounded bg-muted/15 border border-border text-xs">
                                                <div className="flex items-center gap-2">
                                                    <Link2 className="h-3.5 w-3.5 text-muted-foreground" />
                                                    <Badge variant="outline" className="text-[10px]">{link.linkType.replace(/_/g, " ")}</Badge>
                                                    <span>{link.linkName}</span>
                                                </div>
                                                <Button variant="ghost" size="icon" className="h-6 w-6 text-red-400" onClick={() => handleRemoveLink(link.id)}>
                                                    <X className="h-3 w-3" />
                                                </Button>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-xs text-muted-foreground text-center py-3 border border-dashed border-border rounded">No linked resources</p>
                                )}
                            </div>

                            {/* Actions */}
                            <div className="flex gap-2 pt-2">
                                <Button className="flex-1 gap-1.5" onClick={() => window.open(`/api/evidence/${selectedEvidence.id}/download`, "_blank")}>
                                    <Download className="h-4 w-4" />Download
                                </Button>
                                <Button variant="destructive" className="gap-1.5" onClick={() => { handleDelete(selectedEvidence.id); setSelectedEvidence(null); }}>
                                    <Trash2 className="h-4 w-4" />Archive
                                </Button>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* Add Link Modal */}
            {showLinkModal && (
                <div className="fixed inset-0 z-[60] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setShowLinkModal(false)}>
                    <Card className="w-full max-w-sm border-border" onClick={(e) => e.stopPropagation()}>
                        <CardContent className="p-6 space-y-4">
                            <h3 className="text-lg font-bold">Link to Resource</h3>
                            <select
                                className="w-full h-9 px-3 text-sm rounded-md border border-border bg-background text-foreground"
                                value={linkForm.linkType}
                                onChange={(e) => setLinkForm((f) => ({ ...f, linkType: e.target.value }))}
                            >
                                <option value="COMPLIANCE_CONTROL">Compliance Control</option>
                                <option value="RISK">Risk</option>
                                <option value="POLICY">Policy</option>
                                <option value="INCIDENT">Incident</option>
                                <option value="VENDOR">Vendor</option>
                                <option value="KNOWLEDGE_ENTRY">Knowledge Entry</option>
                            </select>
                            <Input
                                placeholder="Resource Name (e.g., ISO 27001:A.8.24)"
                                value={linkForm.linkName}
                                onChange={(e) => setLinkForm((f) => ({ ...f, linkName: e.target.value }))}
                            />
                            <Input
                                placeholder="Resource ID"
                                value={linkForm.linkId}
                                onChange={(e) => setLinkForm((f) => ({ ...f, linkId: e.target.value }))}
                            />
                            <div className="flex gap-2">
                                <Button variant="outline" className="flex-1" onClick={() => setShowLinkModal(false)}>Cancel</Button>
                                <Button className="flex-1" onClick={handleAddLink} disabled={!linkForm.linkId || !linkForm.linkName}>Add Link</Button>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            )}
        </div>
    );
}

'use client';

/**
 * AttackSurface — Intelligence → Attack Surface tab.
 * Monitors organization assets via Shodan API for exposed services,
 * vulnerabilities, SSL issues, and geo mismatches.
 */

import { useState, useCallback, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
    Shield, Scan, AlertTriangle, Lock, Globe, Server, Plus, X, Loader2,
    Download, ShieldAlert, ExternalLink, ChevronDown,
} from 'lucide-react';

// ── Types ──────────────────────────────────────────────────────

interface ExposedService {
    service: string;
    port: number;
    host: string;
    risk: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
    reason: string;
}

interface SSLIssue {
    host: string;
    issue: string;
    severity: 'HIGH' | 'MEDIUM';
}

interface AssetMinimal {
    ip: string;
    hostnames: string[];
    org: string;
    country: string;
    ports: number[];
    vulns: string[];
    lastUpdate: string;
}

interface ScanReport {
    scanDate: string;
    totalAssets: number;
    totalServices: number;
    totalVulnerabilities: number;
    criticalVulns: string[];
    highVulns: string[];
    exposedServices: ExposedService[];
    sslIssues: SSLIssue[];
    geoMismatches: { ip: string; expectedCountry: string; actualCountry: string; hostname: string }[];
    assets: AssetMinimal[];
    riskScore: number;
}

// ── Design tokens ──────────────────────────────────────────────

const CARD_BG = 'rgba(8, 12, 24, 0.85)';
const CARD_BD = 'rgba(56, 189, 248, 0.06)';

const RISK_COLORS: Record<string, string> = {
    CRITICAL: '#f43f5e',
    HIGH: '#f97316',
    MEDIUM: '#eab308',
    LOW: '#22c55e',
};

const RISK_BG: Record<string, string> = {
    CRITICAL: 'rgba(244,63,94,0.08)',
    HIGH: 'rgba(249,115,22,0.08)',
    MEDIUM: 'rgba(234,179,8,0.08)',
    LOW: 'rgba(34,197,94,0.08)',
};

// ── Subtab type ────────────────────────────────────────────────
type FindingTab = 'all' | 'critical' | 'exposed' | 'ssl' | 'geo';

// ── Component ──────────────────────────────────────────────────

export function AttackSurface() {
    const [configured, setConfigured] = useState<boolean | null>(null);
    const [ips, setIPs] = useState<string[]>([]);
    const [domains, setDomains] = useState<string[]>([]);
    const [ipInput, setIpInput] = useState('');
    const [domainInput, setDomainInput] = useState('');
    const [scanning, setScanning] = useState(false);
    const [report, setReport] = useState<ScanReport | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<FindingTab>('all');
    const [credits, setCredits] = useState<number | null>(null);

    // Check configuration on mount
    const checkConfig = useCallback(async () => {
        try {
            const res = await fetch('/api/intelligence/shodan/health');
            const data = await res.json();
            setConfigured(data.connected || false);
            if (data.credits) setCredits(data.credits);
        } catch {
            setConfigured(false);
        }
    }, []);

    // Run on first render
    useEffect(() => { checkConfig(); }, [checkConfig]);

    const addIP = () => {
        const v = ipInput.trim();
        if (v && !ips.includes(v)) { setIPs([...ips, v]); setIpInput(''); }
    };
    const addDomain = () => {
        const v = domainInput.trim();
        if (v && !domains.includes(v)) { setDomains([...domains, v]); setDomainInput(''); }
    };
    const removeIP = (ip: string) => setIPs(ips.filter((i) => i !== ip));
    const removeDomain = (d: string) => setDomains(domains.filter((dm) => dm !== d));

    const runScan = async () => {
        setScanning(true);
        setError(null);
        try {
            const res = await fetch('/api/intelligence/shodan/attack-surface', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ips, domains }),
            });
            const json = await res.json();
            if (!res.ok || json.error) {
                setError(json.error || 'Scan failed');
                if (json.configured === false) setConfigured(false);
            } else {
                setReport(json.data);
            }
        } catch (err) {
            setError('Network error during scan');
            console.error(err);
        } finally {
            setScanning(false);
        }
    };

    // ── Not configured state ──────────────────────────────────
    if (configured === false) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="p-4 rounded-full bg-cyan-500/10 mb-4">
                    <Shield className="h-10 w-10 text-cyan-400" />
                </div>
                <h3 className="text-xl font-semibold text-white mb-2">Attack Surface Monitoring</h3>
                <p className="text-sm text-slate-400 max-w-md mb-4">
                    Configure your Shodan API key in <strong>Settings → Integrations</strong> to enable
                    attack surface monitoring. Get a free key at{' '}
                    <a href="https://account.shodan.io" target="_blank" rel="noopener noreferrer"
                        className="text-cyan-400 hover:text-cyan-300 underline">
                        account.shodan.io
                    </a>
                </p>
                <Button variant="outline" size="sm" onClick={() => window.location.href = '/settings?tab=integrations'}>
                    Go to Settings
                </Button>
            </div>
        );
    }

    // ── Build filtered findings ───────────────────────────────
    const getFilteredAssets = (): AssetMinimal[] => {
        if (!report) return [];
        switch (activeTab) {
            case 'critical':
                return report.assets.filter((a) => a.vulns.length > 0);
            case 'exposed':
                return report.assets.filter((a) =>
                    a.ports.some((p) => [3389, 23, 21, 445, 1433, 3306, 5432, 27017, 6379, 9200].includes(p)),
                );
            default:
                return report.assets;
        }
    };

    const getRiskColor = (score: number) => {
        if (score >= 80) return RISK_COLORS.CRITICAL;
        if (score >= 60) return RISK_COLORS.HIGH;
        if (score >= 30) return RISK_COLORS.MEDIUM;
        return RISK_COLORS.LOW;
    };

    return (
        <div className="space-y-5">
            {/* ── Config Panel ────────────────────────────────── */}
            <div
                className="rounded-xl border p-5"
                style={{ background: CARD_BG, borderColor: CARD_BD }}
            >
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2">
                        <Scan className="h-4 w-4 text-cyan-400" />
                        <span className="text-sm font-semibold text-white uppercase tracking-wider"
                            style={{ fontFamily: 'var(--font-dm-sans), sans-serif' }}>
                            Monitored Assets
                        </span>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-slate-500">
                        {credits !== null && (
                            <span style={{ fontFamily: 'var(--font-jetbrains), monospace' }}>
                                Credits: <span className="text-cyan-400">{credits}</span>
                            </span>
                        )}
                        {report && (
                            <span>
                                Last Scan: {new Date(report.scanDate).toLocaleString()}
                            </span>
                        )}
                    </div>
                </div>

                {/* IP Ranges */}
                <div className="mb-3">
                    <label className="text-xs text-slate-400 mb-1.5 block">IP Addresses / CIDR Ranges</label>
                    <div className="flex gap-2">
                        <Input
                            placeholder="e.g. 203.0.113.0/24"
                            value={ipInput}
                            onChange={(e) => setIpInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addIP()}
                            className="flex-1 bg-white/[0.03] border-white/[0.06] text-sm"
                        />
                        <Button size="sm" variant="outline" onClick={addIP} className="gap-1">
                            <Plus className="h-3 w-3" /> Add
                        </Button>
                    </div>
                    {ips.length > 0 && (
                        <div className="flex flex-wrap gap-1.5 mt-2">
                            {ips.map((ip) => (
                                <span key={ip} className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md bg-cyan-500/10 text-cyan-300 border border-cyan-500/20">
                                    {ip}
                                    <button onClick={() => removeIP(ip)} className="hover:text-white"><X className="h-3 w-3" /></button>
                                </span>
                            ))}
                        </div>
                    )}
                </div>

                {/* Domains */}
                <div className="mb-4">
                    <label className="text-xs text-slate-400 mb-1.5 block">Domains</label>
                    <div className="flex gap-2">
                        <Input
                            placeholder="e.g. astralabs.com"
                            value={domainInput}
                            onChange={(e) => setDomainInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addDomain()}
                            className="flex-1 bg-white/[0.03] border-white/[0.06] text-sm"
                        />
                        <Button size="sm" variant="outline" onClick={addDomain} className="gap-1">
                            <Plus className="h-3 w-3" /> Add
                        </Button>
                    </div>
                    {domains.length > 0 && (
                        <div className="flex flex-wrap gap-1.5 mt-2">
                            {domains.map((d) => (
                                <span key={d} className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md bg-teal-500/10 text-teal-300 border border-teal-500/20">
                                    {d}
                                    <button onClick={() => removeDomain(d)} className="hover:text-white"><X className="h-3 w-3" /></button>
                                </span>
                            ))}
                        </div>
                    )}
                </div>

                <div className="flex gap-2">
                    <Button
                        onClick={runScan}
                        disabled={scanning || (ips.length === 0 && domains.length === 0)}
                        className="gap-2"
                        style={{ background: 'rgba(6,182,212,0.15)', color: '#22d3ee', borderColor: 'rgba(6,182,212,0.3)' }}
                    >
                        {scanning ? <Loader2 className="h-4 w-4 animate-spin" /> : <Scan className="h-4 w-4" />}
                        {scanning ? 'Scanning...' : 'Run Scan'}
                    </Button>
                    {report && (
                        <Button variant="outline" size="sm" className="gap-1.5 text-xs" onClick={() => {
                            const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
                            const url = URL.createObjectURL(blob);
                            const a = document.createElement('a');
                            a.href = url; a.download = `attack-surface-${new Date().toISOString().slice(0, 10)}.json`;
                            a.click(); URL.revokeObjectURL(url);
                        }}>
                            <Download className="h-3.5 w-3.5" /> Export Report
                        </Button>
                    )}
                </div>

                {error && (
                    <div className="mt-3 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-sm text-red-400 flex items-center gap-2">
                        <AlertTriangle className="h-4 w-4 shrink-0" /> {error}
                    </div>
                )}
            </div>

            {/* ── Results ─────────────────────────────────────── */}
            {report && (
                <>
                    {/* Risk Summary Cards */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        {[
                            { label: 'Total Assets', value: report.totalAssets, icon: Server, color: '#22d3ee' },
                            { label: 'Exposed Services', value: report.totalServices, icon: Globe, color: '#f97316', sub: report.exposedServices.length > 0 ? `⚠ ${report.exposedServices.length} risky` : undefined },
                            { label: 'Vulnerabilities', value: report.totalVulnerabilities, icon: ShieldAlert, color: '#f43f5e' },
                            { label: 'SSL Issues', value: report.sslIssues.length, icon: Lock, color: '#eab308' },
                        ].map((card) => {
                            const Icon = card.icon;
                            return (
                                <Card key={card.label} className="border" style={{ background: CARD_BG, borderColor: CARD_BD }}>
                                    <CardContent className="pt-4 pb-3 px-4">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="text-[10px] uppercase tracking-wider text-slate-500"
                                                style={{ fontFamily: 'var(--font-dm-sans), sans-serif' }}>{card.label}</span>
                                            <Icon className="h-3.5 w-3.5" style={{ color: card.color }} />
                                        </div>
                                        <div className="text-2xl font-bold" style={{ color: card.color, fontFamily: 'var(--font-jetbrains), monospace' }}>
                                            {card.value}
                                        </div>
                                        {card.sub && <div className="text-[10px] text-amber-400 mt-0.5">{card.sub}</div>}
                                    </CardContent>
                                </Card>
                            );
                        })}
                    </div>

                    {/* Risk Score Bar */}
                    <div className="rounded-xl border p-4 flex items-center gap-4" style={{ background: CARD_BG, borderColor: CARD_BD }}>
                        <div className="text-center">
                            <div className="text-3xl font-bold" style={{ color: getRiskColor(report.riskScore), fontFamily: 'var(--font-jetbrains), monospace' }}>
                                {report.riskScore}
                            </div>
                            <div className="text-[10px] text-slate-500 uppercase tracking-wider">Risk Score</div>
                        </div>
                        <div className="flex-1">
                            <div className="h-2 rounded-full bg-white/[0.05] overflow-hidden">
                                <div
                                    className="h-full rounded-full transition-all duration-700"
                                    style={{ width: `${report.riskScore}%`, background: getRiskColor(report.riskScore) }}
                                />
                            </div>
                        </div>
                        <div className="text-xs text-slate-400" style={{ fontFamily: 'var(--font-dm-sans), sans-serif' }}>
                            {report.riskScore >= 80 ? 'CRITICAL' : report.riskScore >= 60 ? 'HIGH' : report.riskScore >= 30 ? 'MEDIUM' : 'LOW'}
                        </div>
                    </div>

                    {/* Findings Table */}
