                                            <th className="px-4 py-2">Hostname</th>
                                            <th className="px-4 py-2">Org</th>
                                            <th className="px-4 py-2">Country</th>
                                            <th className="px-4 py-2">Ports</th>
                                            <th className="px-4 py-2">CVEs</th>
                                            <th className="px-4 py-2">Actions</th>
                                        </tr>
                                    </thead>
