'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
    Activity, AlertTriangle, TrendingUp, TrendingDown,
    Radio, Zap, MapPin, RefreshCw, Loader2,
} from 'lucide-react';

interface AnomalyEvent {
    id: string;
    type: string;
    region: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    baseline: number;
    current: number;
    deviationPct: number;
    timestamp: string;
    description: string;
}

interface ConvergenceAlert {
    id: string;
    location: string;
    threatTypes: string[];
    riskScore: number;
    details: string;
    timestamp: string;
}

export function SignalIntelligenceTab() {
    const [anomalies, setAnomalies] = useState<AnomalyEvent[]>([]);
    const [convergences, setConvergences] = useState<ConvergenceAlert[]>([]);
    const [loading, setLoading] = useState(false);
    const [lastRefresh, setLastRefresh] = useState<Date | null>(null);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [anomalyRes, convergenceRes] = await Promise.allSettled([
                fetch('/api/intelligence/anomalies'),
                fetch('/api/intelligence/convergence'),
            ]);

            if (anomalyRes.status === 'fulfilled' && anomalyRes.value.ok) {
                const data = await anomalyRes.value.json();
                setAnomalies(data.anomalies || []);
            }
            if (convergenceRes.status === 'fulfilled' && convergenceRes.value.ok) {
                const data = await convergenceRes.value.json();
                setConvergences(data.alerts || []);
            }
            setLastRefresh(new Date());
        } catch (e) {
            console.error('Signal fetch error:', e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const severityColor = (s: string) => {
        switch (s) {
            case 'critical': return 'bg-red-500/10 text-red-400 border-red-500/30';
            case 'high': return 'bg-amber-500/10 text-amber-400 border-amber-500/30';
            case 'medium': return 'bg-yellow-500/10 text-yellow-400 border-yellow-500/30';
            default: return 'bg-blue-500/10 text-blue-400 border-blue-500/30';
        }
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-amber-500/10 rounded-lg">
                        <Radio className="h-5 w-5 text-amber-400" />
                    </div>
                    <div>
                        <h3 className="text-lg font-semibold">Signal Intelligence</h3>
                        <p className="text-xs text-muted-foreground">
                            Anomaly detection · Convergence alerts · Baseline deviation monitoring
                        </p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    {lastRefresh && (
                        <span className="text-[10px] text-muted-foreground font-mono">
                            Last: {lastRefresh.toLocaleTimeString()}
                        </span>
                    )}
                    <Button variant="outline" size="sm" onClick={fetchData} disabled={loading}>
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                    </Button>
                </div>
            </div>

            {/* Stats Row */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card className="bg-gradient-to-br from-red-500/5 border-red-500/20">
                    <CardContent className="p-4">
                        <div className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Critical Anomalies</div>
                        <div className="text-2xl font-bold text-red-400">
                            {anomalies.filter((a) => a.severity === 'critical').length}
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-gradient-to-br from-amber-500/5 border-amber-500/20">
                    <CardContent className="p-4">
                        <div className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Active Convergences</div>
                        <div className="text-2xl font-bold text-amber-400">{convergences.length}</div>
                    </CardContent>
                </Card>
                <Card className="bg-gradient-to-br from-cyan-500/5 border-cyan-500/20">
                    <CardContent className="p-4">
                        <div className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Total Signals</div>
                        <div className="text-2xl font-bold text-cyan-400">{anomalies.length}</div>
                    </CardContent>
                </Card>
                <Card className="bg-gradient-to-br from-emerald-500/5 border-emerald-500/20">
                    <CardContent className="p-4">
                        <div className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Avg Deviation</div>
                        <div className="text-2xl font-bold text-emerald-400">
                            {anomalies.length > 0
                                ? `${Math.round(anomalies.reduce((s, a) => s + a.deviationPct, 0) / anomalies.length)}%`
                                : '—'}
                        </div>
                    </CardContent>
                </Card>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Anomalies Column */}
                <div>
                    <h4 className="text-sm font-semibold flex items-center gap-2 mb-3">
                        <Activity className="h-4 w-4 text-amber-400" />
                        Temporal Baseline Anomalies
                    </h4>
                    <ScrollArea className="h-[500px] rounded-lg border border-border/30 bg-card/10">
                        <div className="p-3 space-y-2">
                            {anomalies.length === 0 ? (
                                <div className="flex flex-col items-center justify-center py-16 text-muted-foreground">
                                    <Activity className="h-10 w-10 mb-3 opacity-20" />
                                    <p className="text-sm">No anomalies detected</p>
                                    <p className="text-xs mt-1">Click refresh to scan for baseline deviations</p>
                                </div>
                            ) : (
                                anomalies.map((a) => (
                                    <Card key={a.id} className="bg-card/30">
                                        <CardContent className="p-3">
                                            <div className="flex items-center justify-between mb-2">
                                                <div className="flex items-center gap-2">
                                                    <Badge variant="outline" className={`text-[10px] ${severityColor(a.severity)}`}>
                                                        {a.severity}
                                                    </Badge>
                                                    <span className="text-sm font-medium">{a.type}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    {a.deviationPct > 0 ? (
                                                        <TrendingUp className="h-3 w-3 text-red-400" />
                                                    ) : (
                                                        <TrendingDown className="h-3 w-3 text-emerald-400" />
                                                    )}
                                                    <span className={`text-xs font-bold ${a.deviationPct > 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                                                        {a.deviationPct > 0 ? '+' : ''}{a.deviationPct}%
                                                    </span>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-1 text-[10px] text-muted-foreground mb-1">
                                                <MapPin className="h-3 w-3" /> {a.region}
                                            </div>
                                            <p className="text-xs text-slate-400">{a.description}</p>
                                            <div className="flex gap-4 mt-2 text-[10px] text-muted-foreground">
                                                <span>Baseline: {a.baseline}</span>
                                                <span>Current: {a.current}</span>
                                                <span>{new Date(a.timestamp).toLocaleTimeString()}</span>
                                            </div>
                                        </CardContent>
                                    </Card>
                                ))
                            )}
                        </div>
                    </ScrollArea>
                </div>

                {/* Convergence Alerts */}
                <div>
                    <h4 className="text-sm font-semibold flex items-center gap-2 mb-3">
                        <Zap className="h-4 w-4 text-red-400" />
                        Geographic Convergence Alerts
                    </h4>
                    <ScrollArea className="h-[500px] rounded-lg border border-border/30 bg-card/10">
                        <div className="p-3 space-y-2">
                            {convergences.length === 0 ? (
                                <div className="flex flex-col items-center justify-center py-16 text-muted-foreground">
                                    <Zap className="h-10 w-10 mb-3 opacity-20" />
                                    <p className="text-sm">No convergence alerts</p>
                                    <p className="text-xs mt-1">Alerts appear when multiple threat types cluster geographically</p>
                                </div>
                            ) : (
                                convergences.map((c) => (
                                    <Card key={c.id} className="bg-card/30 border-red-500/10">
                                        <CardContent className="p-3">
                                            <div className="flex items-center justify-between mb-2">
                                                <div className="flex items-center gap-2">
                                                    <AlertTriangle className="h-4 w-4 text-red-400" />
                                                    <span className="text-sm font-semibold">{c.location}</span>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <span className="text-xs font-bold text-red-400">
                                                        Risk: {c.riskScore}/100
                                                    </span>
                                                </div>
                                            </div>
                                            <div className="flex flex-wrap gap-1 mb-2">
                                                {c.threatTypes.map((t) => (
                                                    <Badge key={t} variant="outline" className="text-[9px] border-amber-500/30 text-amber-400">
                                                        {t}
                                                    </Badge>
                                                ))}
                                            </div>
                                            <p className="text-xs text-slate-400">{c.details}</p>
                                            <div className="text-[10px] text-muted-foreground mt-2">
                                                {new Date(c.timestamp).toLocaleString()}
                                            </div>
                                        </CardContent>
                                    </Card>
                                ))
                            )}
                        </div>
                    </ScrollArea>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
    BrainCircuit, Globe, Loader2, Crosshair, Users, Shield,
    CheckCircle2, AlertTriangle, FileText, Sparkles,
} from 'lucide-react';
import type { ThreatBrief } from '@/lib/ai/osint-engine';

export function ThreatBriefingTab() {
    const [industry, setIndustry] = useState('Financial Services');
    const [region, setRegion] = useState('Global');
    const [focus, setFocus] = useState('');
    const [brief, setBrief] = useState<ThreatBrief | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // World brief state
    const [worldBrief, setWorldBrief] = useState<string | null>(null);
    const [worldBriefLoading, setWorldBriefLoading] = useState(false);

    const handleGenerateBrief = async () => {
        setLoading(true);
        setError('');
        try {
            const res = await fetch('/api/intelligence/osint', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ industry, region, focusAreas: focus }),
            });
            if (!res.ok) throw new Error('Failed to generate brief');
            const data = await res.json();
            setBrief(data);
        } catch (e: unknown) {
            setError(e instanceof Error ? e.message : 'Unknown error');
        } finally {
            setLoading(false);
        }
    };

    const handleWorldBrief = async () => {
        setWorldBriefLoading(true);
        try {
            const res = await fetch('/api/intelligence/brief');
            if (!res.ok) throw new Error('Failed to fetch world brief');
            const data = await res.json();
            setWorldBrief(data.brief || data.summary || 'No brief available.');
        } catch {
            setWorldBrief('Unable to generate world brief. Configure AI provider in Settings.');
        } finally {
            setWorldBriefLoading(false);
        }
    };

    return (
        <div className="space-y-6">
            {/* AI World Brief Banner */}
            <Card className="bg-gradient-to-r from-cyan-500/5 via-purple-500/5 to-transparent border-cyan-500/20">
                <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-cyan-500/10 rounded-lg">
                                <Sparkles className="h-5 w-5 text-cyan-400" />
                            </div>
                            <div>
                                <CardTitle className="text-lg">AI World Brief</CardTitle>
                                <CardDescription>AI-synthesized global threat summary</CardDescription>
                            </div>
                        </div>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={handleWorldBrief}
                            disabled={worldBriefLoading}
                            className="border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
                        >
                            {worldBriefLoading ? (
                                <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Generating...</>
                            ) : (
                                <><BrainCircuit className="h-4 w-4 mr-2" />Generate Brief</>
                            )}
                        </Button>
                    </div>
                </CardHeader>
                {worldBrief && (
                    <CardContent>
                        <div className="p-4 rounded-lg bg-secondary/20 border border-border/30 text-sm text-slate-300 whitespace-pre-line">
                            {worldBrief}
                        </div>
                    </CardContent>
                )}
            </Card>

            {/* Industry Threat Brief */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-1 space-y-4">
                    <Card className="bg-card/40 border-primary/20">
                        <CardHeader>
                            <CardTitle className="text-lg flex items-center gap-2">
                                <Globe className="h-5 w-5 text-cyan-400" />
                                Generate Threat Brief
                            </CardTitle>
                            <CardDescription>AI-powered threat landscape analysis</CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="space-y-2">
                                <Label htmlFor="brief-industry">Industry Sector</Label>
                                <select
                                    id="brief-industry"
                                    value={industry}
                                    onChange={(e) => setIndustry(e.target.value)}
                                    className="w-full h-9 rounded-md border border-input bg-transparent px-3 py-1 text-sm"
                                >
                                    {['Financial Services', 'Healthcare', 'Technology', 'Manufacturing', 'Retail', 'Government', 'Energy', 'Education', 'Telecommunications'].map((opt) => (
                                        <option key={opt} value={opt}>{opt}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="brief-region">Region</Label>
                                <select
                                    id="brief-region"
                                    value={region}
                                    onChange={(e) => setRegion(e.target.value)}
                                    className="w-full h-9 rounded-md border border-input bg-transparent px-3 py-1 text-sm"
                                >
                                    {['Global', 'North America', 'Europe (EMEA)', 'Asia-Pacific', 'Middle East', 'Latin America'].map((opt) => (
                                        <option key={opt} value={opt}>{opt}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="brief-focus">Focus Areas (optional)</Label>
                                <Textarea
                                    id="brief-focus"
                                    placeholder="e.g. Ransomware, supply chain attacks..."
                                    value={focus}
                                    onChange={(e) => setFocus(e.target.value)}
                                    className="min-h-[60px]"
                                />
                            </div>
                            <Button onClick={handleGenerateBrief} disabled={loading} className="w-full">
                                {loading ? (
                                    <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Analyzing...</>
                                ) : (
                                    <><BrainCircuit className="h-4 w-4 mr-2" />Generate Threat Brief</>
                                )}
                            </Button>
                            {error && <p className="text-xs text-red-400">{error}</p>}
                        </CardContent>
                    </Card>
                </div>

                <div className="md:col-span-2">
                    {!brief ? (
                        <div className="h-full flex flex-col items-center justify-center p-12 border border-dashed border-border/30 rounded-xl bg-card/10">
                            <Globe className="h-16 w-16 mb-4 opacity-20 text-muted-foreground" />
                            <h3 className="text-xl font-semibold text-muted-foreground mb-2">Threat Intelligence Ready</h3>
                            <p className="text-center max-w-md text-muted-foreground">
                                Select your industry and region to generate an AI-powered threat landscape analysis.
                            </p>
                        </div>
                    ) : (
                        <ScrollArea className="h-[600px]">
                            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 pr-4">
                                {/* Brief Header */}
                                <Card className="border-primary/30 bg-card/40">
                                    <CardContent className="p-4">
                                        <div className="flex items-start justify-between mb-3">
                                            <div>
                                                <Badge variant="outline" className="mb-1 border-cyan-500/30 text-cyan-400">AI Generated</Badge>
                                                <h3 className="text-lg font-bold">Threat Landscape: {brief.industry} — {brief.region}</h3>
                                            </div>
                                            <span className={`text-xs font-bold px-2 py-1 rounded-full ${brief.overallRiskLevel === 'critical' ? 'bg-red-500/10 text-red-400' : brief.overallRiskLevel === 'high' ? 'bg-amber-500/10 text-amber-400' : 'bg-blue-500/10 text-blue-400'}`}>
                                                {brief.overallRiskLevel.toUpperCase()} RISK
                                            </span>
                                        </div>
                                        <p className="text-sm text-muted-foreground">{brief.summary}</p>
                                        <div className="flex gap-4 mt-3 text-xs text-muted-foreground">
                                            <span>Confidence: {brief.confidence}%</span>
                                            <span>Generated: {new Date(brief.generatedAt).toLocaleString()}</span>
                                        </div>
                                    </CardContent>
                                </Card>

                                {/* Top Threats */}
                                <div className="space-y-2">
                                    <h4 className="text-sm font-semibold flex items-center gap-2">
                                        <Crosshair className="h-4 w-4 text-red-400" /> Top Threats
                                    </h4>
                                    {brief.topThreats.map((threat, i) => (
                                        <Card key={i} className="bg-card/30">
                                            <CardContent className="p-3">
                                                <div className="flex items-center gap-2 mb-1">
                                                    <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${threat.severity === 'critical' ? 'bg-red-500/10 text-red-400' : threat.severity === 'high' ? 'bg-amber-500/10 text-amber-400' : 'bg-blue-500/10 text-blue-400'}`}>
