            {/* Expanded detail */}
            {expanded && (
                <div className="border-t border-border/20 px-3 py-2 space-y-2 animate-in slide-in-from-top-1 duration-150">
                    {/* Intelligence gaps */}
                    {summary.gaps.length > 0 && (
                        <div className="space-y-1">
